func run():
    var wav = load("res://audio/placeholder/music_loop.wav") as AudioStreamWAV
    if wav:
        print("loop_mode=", wav.loop_mode, " LOOP_FORWARD=", AudioStreamWAV.LOOP_FORWARD)
        print("loop_begin=", wav.loop_begin)
        print("loop_end=", wav.loop_end)
        print("mix_rate=", wav.mix_rate, " stereo=", wav.stereo)
        print("data bytes=", wav.data.size())
    else:
        print("load returned null")
    quit(0)

